fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 {
        host::display::state_set(0, 1 - host::display::state_get(0));
    }
    host::display::state_set(2, down);
    let running: i32 = host::display::state_get(0);
    let mut e: i32 = host::display::state_get(1);
    if running == 1 { e = e + 1; }
    host::display::state_set(1, e);
    let mins: i32 = e / 3600;
    let secs: i32 = (e / 60) % 60;
    host::display::clear(0x101010);
    host::display::draw_string(8, 10, "STOPWATCH", 0x808080, 1);
    let mut x: i32 = 8;
    if mins < 10 {
        host::display::draw_number(x, 40, 0, 0xffffff, 4);
        x = x + 24;
    }
    host::display::draw_number(x, 40, mins, 0xffffff, 4);
    host::display::draw_string(60, 40, ":", 0xffffff, 4);
    let mut sx: i32 = 84;
    if secs < 10 {
        host::display::draw_number(sx, 40, 0, 0xffffff, 4);
        sx = sx + 24;
    }
    host::display::draw_number(sx, 40, secs, 0xffffff, 4);
    if running == 1 {
        host::display::fill_rect(8, 90, 10, 10, 0x00ff00);
        host::display::draw_string(24, 90, "RUNNING - TAP TO PAUSE", 0x00ff00, 1);
    } else {
        host::display::fill_rect(8, 90, 10, 10, 0x804040);
        host::display::draw_string(24, 90, "PAUSED - TAP TO START", 0x808080, 1);
    }
    host::display::present();
}
